/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.exception.NotFoundException;
import net.civeira.phylax.feature.observe.issue.HyperLogLog;
import net.civeira.phylax.feature.observe.issue.IssueAliases;
import net.civeira.phylax.feature.observe.issue.IssueTracker;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRuleChangeSet;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRuleEffectOptions;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRuleFieldOptions;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.gateway.ObservedFingerprintRuleCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueStatusOptions;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueFilter;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAlias;
import net.civeira.phylax.feature.observe.observedissuealias.domain.ObservedIssueAliasChangeSet;
import net.civeira.phylax.feature.observe.observedissuealias.domain.gateway.ObservedIssueAliasCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissuealias.domain.gateway.ObservedIssueAliasFilter;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueCommentChangeSet;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.gateway.ObservedIssueCommentCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.gateway.ObservedIssueCommentFilter;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

/**
 * Teamwork on the issues from the viewer (WRITE level, checked by the api): merge, assign, ignore
 * until a moment or a count, comment, create its task in the issue tracker, and split with a
 * fingerprint rule. These operations write through the domain repositories: the audit of the
 * generated use cases does not record them.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveIssueWorkflow {

  private final ObservedIssueCommandRepositoryGateway issues;
  private final ObservedIssueAliasCommandRepositoryGateway aliases;
  private final ObservedIssueCommentCommandRepositoryGateway comments;
  private final ObservedFingerprintRuleCommandRepositoryGateway rules;
  private final IssueAliases aliasRegistry;
  private final IssueTracker tracker;

  /** Comment of an issue as the viewer shows it. */
  public record CommentRow(String uid, String author, String authorName, String text,
      long createdAt) {}

  /**
   * Merges {@code uid} into {@code into}: the counts and the users add up, the fingerprint of the
   * merged issue (and its own aliases) point to the target, and the merged one is MERGED.
   */
  @Transactional
  public Map<String, Object> merge(final String uid, final String into) {
    if (uid.equals(into)) {
      throw new IllegalArgumentException("An issue cannot be merged into itself");
    }
    ObservedIssue source = issue(uid);
    ObservedIssue target = issue(into);
    if (ObservedIssueStatusOptions.MERGED == target.getStatus()) {
      throw new IllegalArgumentException("The target issue is merged into another one");
    }
    for (ObservedIssueAlias alias : aliases
        .list(ObservedIssueAliasFilter.builder().issue(ObservedIssueReference.of(uid)).build())) {
      aliases.update(alias,
          alias.update(new ObservedIssueAliasChangeSet().issue(ObservedIssueReference.of(into))));
    }
    aliases.create(ObservedIssueAlias.create(new ObservedIssueAliasChangeSet().newUid()
        .origin(ObservedSourceReference.of(source.getOriginUid()))
        .fingerprint(source.getFingerprint()).issue(ObservedIssueReference.of(into))));
    HyperLogLog users = HyperLogLog.fromBase64(target.getUsersSketch().orElse(null))
        .merge(HyperLogLog.fromBase64(source.getUsersSketch().orElse(null)));
    HyperLogLog tenants = HyperLogLog.fromBase64(target.getTenantsSketch().orElse(null))
        .merge(HyperLogLog.fromBase64(source.getTenantsSketch().orElse(null)));
    OffsetDateTime first =
        min(target.getFirstSeenAt().orElse(null), source.getFirstSeenAt().orElse(null));
    OffsetDateTime last =
        max(target.getLastSeenAt().orElse(null), source.getLastSeenAt().orElse(null));
    boolean sourceNewer =
        null != source.getLastSeenAt().orElse(null) && source.getLastSeenAt().get().equals(last);
    issues.update(target,
        target.recordOccurrence(count(target) + count(source), first, last, target.getStatus(),
            (sourceNewer ? source : target).getLastEventId().orElse(null),
            (sourceNewer ? source : target).getLastTraceId().orElse(null),
            target.getFirstRelease().or(source::getFirstRelease).orElse(null),
            (sourceNewer ? source : target).getRelease().orElse(null), (int) users.estimate(),
            (int) tenants.estimate(), users.toBase64(), tenants.toBase64()));
    issues.update(source, source.mergeInto(into));
    aliasRegistry.reload();
    return Map.of("merged", uid, "into", into);
  }

  /** Assigns the issue to {@code user}, or unassigns it with null. */
  @Transactional
  public Map<String, Object> assign(final String uid, final String user) {
    ObservedIssue issue = issue(uid);
    issues.update(issue, issue.assign(null == user ? "" : user, null == user ? "" : user));
    return Map.of("assignee", null == user ? "" : user);
  }

  /**
   * Ignores the issue until {@code hours} from now and/or until its count grows by {@code events}.
   */
  @Transactional
  public Map<String, Object> snooze(final String uid, final Integer hours, final Integer events) {
    ObservedIssue issue = issue(uid);
    OffsetDateTime until =
        null == hours || hours <= 0 ? null : OffsetDateTime.now(ZoneOffset.UTC).plusHours(hours);
    Integer limit = null == events || events <= 0 ? null : count(issue) + events;
    issues.update(issue, issue.snooze(until, limit));
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("until", null == until ? null : until.toInstant().toEpochMilli());
    result.put("untilCount", limit);
    return result;
  }

  @Transactional
  public List<CommentRow> comments(final String uid) {
    return comments
        .list(ObservedIssueCommentFilter.builder().issue(ObservedIssueReference.of(uid)).build())
        .stream()
        .map(comment -> new CommentRow(comment.getUid(), comment.getAuthor(),
            comment.getAuthorName(), comment.getText(),
            comment.getCreatedAt().toInstant().toEpochMilli()))
        .sorted(Comparator.comparingLong(CommentRow::createdAt)).toList();
  }

  @Transactional
  public CommentRow comment(final String uid, final String author, final String text) {
    if (null == text || text.isBlank()) {
      throw new IllegalArgumentException("Empty comment");
    }
    issue(uid);
    ObservedIssueComment created =
        comments.create(ObservedIssueComment.create(new ObservedIssueCommentChangeSet().newUid()
            .issue(ObservedIssueReference.of(uid)).author(author).authorName(author)
            .text(text.length() > 10_000 ? text.substring(0, 10_000) : text)
            .createdAt(OffsetDateTime.now(ZoneOffset.UTC))));
    return new CommentRow(created.getUid(), author, author, created.getText(),
        created.getCreatedAt().toInstant().toEpochMilli());
  }

  /** Creates the task in the tracker once: a second call returns the same URL. */
  @Transactional
  public Map<String, Object> ticket(final String uid, final String viewerUrl) {
    ObservedIssue issue = issue(uid);
    if (issue.getTrackerUrl().filter(url -> !url.isBlank()).isPresent()) {
      return Map.of("url", issue.getTrackerUrl().get());
    }
    String description = issue.getTitle() + "\n\n"
        + issue.getCulprit().map(c -> "Culprit: " + c + "\n").orElse("") + "Events: " + count(issue)
        + ", users: " + (null == issue.getUsers() ? 0 : issue.getUsers()) + "\n"
        + issue.getRelease().map(r -> "Release: " + r + "\n").orElse("") + "Viewer: " + viewerUrl
        + "\n";
    String url = tracker.create(issue.getTitle(), description);
    issues.update(issue, issue.linkTicket(url));
    return Map.of("url", url);
  }

  /** Splits: a group-as rule on the message of the events of the origin of the issue. */
  @Transactional
  public Map<String, Object> split(final String uid, final String pattern, final String name) {
    ObservedIssue issue = issue(uid);
    if (net.civeira.phylax.feature.observe.issue.SafeRegex.compile(pattern).isEmpty()) {
      throw new IllegalArgumentException("Invalid pattern (at most 200 characters)");
    }
    ObservedFingerprintRule rule =
        rules.create(ObservedFingerprintRule.create(new ObservedFingerprintRuleChangeSet().newUid()
            .name(null == name || name.isBlank() ? "Split of " + issue.getTitle() : name)
            .origin(ObservedSourceReference.of(issue.getOriginUid()))
            .field(ObservedFingerprintRuleFieldOptions.MESSAGE).pattern(pattern)
            .effect(ObservedFingerprintRuleEffectOptions.GROUP_AS)).enable());
    return Map.of("rule", rule.getUid());
  }

  private ObservedIssue issue(final String uid) {
    return issues.find(ObservedIssueFilter.builder().uid(uid).build())
        .orElseThrow(() -> new NotFoundException("Issue " + uid));
  }

  private static int count(final ObservedIssue issue) {
    return null == issue.getCount() ? 0 : issue.getCount();
  }

  private static OffsetDateTime min(final OffsetDateTime a, final OffsetDateTime b) {
    return null == a ? b : null == b ? a : a.isBefore(b) ? a : b;
  }

  private static OffsetDateTime max(final OffsetDateTime a, final OffsetDateTime b) {
    return null == a ? b : null == b ? a : a.isAfter(b) ? a : b;
  }
}
